/bin/bash -lc "Rscript - <<'RS'
for (s in c('97','98','99')) {
  f <- file.path('/workspace', paste0('res_1vs',s,'.rds'))
  cat('\\n===', s, '===\\n')
  x <- readRDS(f)
  cat('class:', paste(class(x), collapse=','), '\\n')
  cat('isS4:', isS4(x), '\\n')
  if (isS4(x)) {
    cat('slots:', paste(slotNames(x), collapse=', '), '\\n')
    for (sl in slotNames(x)) {
      v <- slot(x, sl)
      cat('slot', sl, 'class', paste(class(v), collapse=','), 'length/dim', if(is.null(dim(v))) length(v) else paste(dim(v), collapse='x'), '\\n')
    }
  }
}
RS"

